91	
92	// handleCreationSubmit handles form submission.
93	//
94	// The row goes on screen before the request goes out: creating is a network
95	// call, and the tree used to be emptied by a full refresh for the whole of it —
96	// the user saw a blank table and a silent footer, with nothing to say the thing
97	// they had just asked for was on its way. The row is the answer, and the
98	// registry is what keeps it honest (see jobs.go).
99	func (m Model) handleCreationSubmit(msg components.CreationFormSubmitMsg) (tea.Model, tea.Cmd) {
100		m.mode = ModeNormal
101		m.creationForm = nil
102	
103		if m.shared.Forge == nil {
104			m.error = "Not connected to a forge"
105			return m, nil
106		}
107	
108		target := m.createTarget(msg)
109		if m.busy(target) {
110			return m, m.footer.Warn(busyMessage)
111		}
112	
113		nodeType := NodeTypeProject
114		work := m.createProject(msg, target)
115		if msg.FormType == components.FormTypeGroup {
116			nodeType = NodeTypeGroup
117			work = m.createGroup(msg, target)
118		}
119	
120		m.insertCreatingNode(msg, target, nodeType)
121		return m, jobs.Start(createRun(target, msg.Name), work)
122	}
123	
124	// createTarget is the path the row and the run are both keyed on, predicted
125	// from the parent being browsed and the slug the name becomes.
126	//
127	// A prediction, because the forge answers with the real one and is free to
128	// differ — but the row has to exist before there is an answer, so it needs a
129	// key that can be computed now. settleCreating is what reconciles the two.
130	func (m Model) createTarget(msg components.CreationFormSubmitMsg) string {
131		slug := slugify(msg.Name)
132		if m.creationParentName == "" {
133			return slug
134		}
135		return m.creationParentName + "/" + slug
136	}
137	
138	// insertCreatingNode puts the placeholder at the level being browsed.
139	//
140	// At the end of the level rather than sorted in: the default is the forge's own
141	// order, which is insertion order, so the row appears where a reader's eye is
142	// free — the bottom — instead of displacing rows above the cursor. Under a sort
143	// the table places it like any other row.
144	func (m *Model) insertCreatingNode(msg components.CreationFormSubmitMsg, target string, nodeType NodeType) {
145		node := &TreeNode{
146			Name:       msg.Name,
147			FullPath:   target,
148			Type:       nodeType,
149			Creating:   true,
150			Visibility: msg.Visibility,
151			Parent:     m.currentGroupNode,
152		}
153		if m.currentGroupNode == nil {
154			m.nodes = append(m.nodes, node)
155		} else {
156			m.currentGroupNode.Children = append(m.currentGroupNode.Children, node)
157		}
158		m.updateTableRows()
159	}
160	
161	// replaceCreating swaps the placeholder keyed on target for what the forge
162	// answered, or drops it when replacement is nil.
163	//
164	// It walks the loaded tree rather than the current level: the user is free to
165	// drill elsewhere while the request is in flight, and the row belongs to the
166	// level it was made in.
167	func replaceCreating(nodes []*TreeNode, target string, replacement *TreeNode) ([]*TreeNode, bool) {
168		for i, node := range nodes {
169			if node.Creating && node.FullPath == target {
170				if replacement == nil {
171					return append(nodes[:i], nodes[i+1:]...), true
172				}
173				replacement.Parent = node.Parent
174				nodes[i] = replacement
175				return nodes, true
176			}
177			if children, ok := replaceCreating(node.Children, target, replacement); ok {
178				node.Children = children
179				return nodes, true
180			}
181		}
182		return nodes, false
183	}
184	
185	// carryOverCreating keeps the placeholders of a level that is being replaced.
186	//
187	// A reload swaps the level wholesale — `ctrl+r` at the root, a ChildrenLoadedMsg
188	// inside a group — and a create still in flight has nothing yet to be replaced
189	// by. Dropped here, its row would vanish mid-request while the registry went on
190	// tracking the run: `:jobs` would show work the tree had stopped admitting to,
191	// and settleCreating would have nothing left to resolve when the answer came.
192	func carryOverCreating(previous, fresh []*TreeNode) []*TreeNode {
193		for _, node := range previous {
194			if node.Creating {
195				fresh = append(fresh, node)
196			}
197		}
198		return fresh
199	}
200	
201	// settleCreating resolves the placeholder and rebuilds the rows.
202	func (m *Model) settleCreating(target string, replacement *TreeNode) {
203		m.nodes, _ = replaceCreating(m.nodes, target, replacement)
204		m.updateTableRows()
205	}
206	
207	// selectRow puts the cursor on the row for path, if it is on screen. It is what
208	// replaces the pendingSelectPath round trip: the node is already in the tree,
209	// so there is no refresh to wait for and no path to chase.
210	func (m *Model) selectRow(path string) {
211		for i, row := range m.table.Visible() {
212			if row.node.FullPath == path {
213				m.table.SetCursor(i)
214				return
215			}
216		}
217	}
218	
219	// createGroup creates a new namespace on the forge.
220	func (m Model) createGroup(msg components.CreationFormSubmitMsg, target string) tea.Cmd {
221		backend := m.shared.Forge
222		spec := forge.NewNamespace{
223			Name:        msg.Name,
224			Slug:        slugify(msg.Name),
225			Description: msg.Description,
226			Visibility:  msg.Visibility,
227			ParentID:    msg.ParentID,
228		}
229	
230		return func() tea.Msg {
231			ctx, cancel := context.WithTimeout(context.Background(), forgeCallTimeout)
232			defer cancel()
233			ns, err := backend.CreateNamespace(ctx, spec)
234			if err != nil {
235				return GroupCreatedMsg{Target: target, Error: err}
236			}
237			return GroupCreatedMsg{Namespace: ns, Target: target}
238		}
239	}
240	
241	// What a forge call may take before the run gives up on it. A create is not
242	// cancellable by the user (jobs.Kind.Cancellable — a request already sent cannot
243	// be un-sent), so the bound is what keeps a stalled connection from holding the
244	// row, and the target, busy for the life of the session.
245	//
246	// The initial commit gets far longer than the rest: GitHub takes one request per
247	// file, and a template may hold template.MaxFiles of them.
248	const (
249		forgeCallTimeout     = time.Minute
250		initialCommitTimeout = 10 * time.Minute
251	)
252	
253	// slugify turns a display name into the path segment a forge wants.
254	func slugify(name string) string {
255		return strings.ToLower(strings.ReplaceAll(name, " ", "-"))
