// New creates a new instance of the explorer model
func New(cfg *config.Config, sharedState *shared.State) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	m := Model{
		config:        cfg,
		shared:        sharedState,
		templateCache: template.NewCache(),
		nodes:         []*TreeNode{},
		loading:       false,
		mode:          ModeNormal,
		selection:     newCloneSelection(),
		table: datatable.New(datatable.Config[explorerRow]{
			Columns: explorerColumns(),
			// The forge's own order: loadChildren stacks the namespaces, then
			// the repositories. It used to be a sort by node type, which on
			// that list is the identity — so the opening screen is unchanged,
			// and what is gained is that `.` now has "no sort" as a stop, so
			// the forge's order is reachable again after cycling away from it.
			SortColumn: -1,
		}),
		spinner: s,
	}
	m.seedFromIndex()
	return m
}

// Init initializes the model
// handleJobsChanged takes the router's snapshot.
//
// Two screens read it now. The clone list reads its own run, and the tree reads
// the creates and deletes running against the rows it is showing — liveRuns is
// what keeps a scan in `ws` from spinning a row here, rather than this handler
// declining to keep the snapshot at all.
//
// It is the only writer of the two fields, and there is nothing to reconcile:
// the snapshot replaces what was held rather than being merged into it.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs

	if m.clone != nil {
		if run, ok := cloneRunFrom(msg.Runs); ok {
			m.clone.setRun(run, m.jobFrame)
		}
		return m, nil
	}
	// The rows are rebuilt from the new snapshot and the last frame held.
	m.updateTableRows()
	return m, nil
}

// handleFrameMsg takes the animation's frame. The clone list keeps its own copy
// of the run, so only the frame is rebuilt into it; the run is not touched.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.jobFrame = msg.Frame
	m.footer.SetSpinnerFrame(msg.RenderedFrame)

	if m.clone != nil {
		m.clone.setRun(m.clone.run, msg.Frame)
		return m, nil
	}
	m.updateTableRows()
	return m, nil
}

// failureSummary names one failure and counts the rest — the footer is one line.
func failureSummary(failed []string) string {
	if len(failed) == 1 {
		return "Failed to clone " + failed[0] + " — check logs"
	}
	return "Failed to clone " + failed[0] + " and " +
		plural(len(failed)-1, "other") + " — check logs"
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

// handleCloneEsc cancels a running pipeline, or closes a finished one.
//
// The two are one key because they are one intent — "I am done with this" — and
// separating them would need the user to know which state the list is in. A
// second press while cancelling does nothing: forcing would mean killing a
// `git clone` mid-write, which is the half-repository decision 12 rules out.
func (m Model) handleCloneEsc() (tea.Model, tea.Cmd) {
	if m.clone == nil {

	case CloneEventMsg:
		return m.handleCloneEvent(msg)

	case CloneRunFinishedMsg:
		return m.handleCloneRunFinished()

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case jobs.FrameMsg:
		return m.handleFrameMsg(msg)

	case components.CreationFormSubmitMsg:
		return m.handleCreationSubmit(msg)


// handleSpinnerTick advances the spinner the view owns, which is now the
// **load** and nothing else.
//
// It used to drive the clone rows as well, and that was the fourth hand-stamped
// chain D5 removed: the rows take the router's frame from the broadcast now, so
// a clone keeps turning whether or not this view is on screen — and cannot
// freeze on frame zero if this chain dies.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.loading && m.refreshing == 0 {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	// The load is reported in the footer, so the frame has to reach it — a
	// spinner stuck on frame zero reads as a hang.
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handleOpenInBrowser opens the selected node's web URL in the default browser

