25	// A-16 (DEVDESK-143), the cross-cutting guard, started with the :jobs pilot
26	// (DEVDESK-142).
27	//
28	// The guard answers one question for every view the router can build: is it on
29	// the activity column, is it waiting for its migration, or is it exempt for a
30	// stated reason? A view that is none of the three fails the test by name. For a
31	// migrated view it also checks the column, the help legend, the retired
32	// mechanisms in its declared sources (including its own ticks), and the footer
33	// of its selected row. Declared exceptions may only shrink, and follow their
34	// stories: pendingTables here, declaredRowChains in animation_guard_test.go.
35	
36	// activityView is what a migrated view exposes to the guard: read-only tables,
37	// keyed "<view>/<table>".
38	type activityView interface {
39		ActivityTables() map[string]datatable.ActivityTable
40	}
41	
42	// migratedTables are the tables already on the activity column, by view.
43	var migratedTables = map[command.ViewType][]string{
44		command.ViewJobs:         {"jobs/runs", "jobs/targets"},
45		command.ViewWorkspaces:   {"ws"},
46		command.ViewSecurity:     {"sec/inventory"},
47		command.ViewOCIResources: {"oci/images"},
48	}
49	
50	// pendingTable is a table that still has to move to the activity column.
51	type pendingTable struct {
52		Table string
53		View  command.ViewType
54		Story string
55	}
56	
57	// pendingTables may only shrink: each migration story removes its own entries.
58	var pendingTables = []pendingTable{
59		{"oci/registry-browser", command.ViewOCIResources, "A-09a2"},
60		{"oci/networks", command.ViewOCIResources, "A-09b"},
61		{"oci/volumes", command.ViewOCIResources, "A-09b"},
62		{"oci/registries", command.ViewOCIResources, "A-09b"},
63		{"explorer/tree", command.ViewGitExplorer, "A-10a"},
64		{"explorer/clone-list", command.ViewGitExplorer, "A-10b"},
65		{"templates", command.ViewTemplates, "A-11"},
66		{"netdiag/ports", command.ViewNetdiag, "A-12"},
67		{"agent-usage/agents", command.ViewAgentUsage, "A-13"},
68		{"containers", command.ViewContainers, "A-14"},
69	}
70	
71	// maxPendingTables is the ceiling: adding an exception means raising both the
72	// list and this constant in the same diff, which is visible in review. Lower it
73	// with every migration.
74	const maxPendingTables = 10
75	
76	// exemptViews have no long-running operation to show per row (inventory:
77	// "sans objet" or out of the batch), each with its reason.
78	var exemptViews = map[command.ViewType]string{
79		command.ViewDashboard:     "no table with row operations; the dashboard is a summary",
80		command.ViewStatus:        "monitors are polled as a whole, not per-row operations",
81		command.ViewGitAuth:       "a form, no table",
82		command.ViewConfiguration: "a form of settings, no table of operations",
83		command.ViewAbout:         "static facts, no table",
84		command.ViewFiles:         "out of the batch, candidate for a later S story (the delete goes through the registry, no story covers it)",
85		command.ViewViewer:        "a document pane, no table",
86	}
