96	func TestActivityGuardPendingListOnlyShrinks(t *testing.T) {
97		if got := len(pendingTables); got > maxPendingTables {
98			t.Errorf("pendingTables has %d entries, ceiling is %d: the list may only shrink (A-16 criterion 6)", got, maxPendingTables)
99		}
100		seen := map[string]bool{}
101		for _, p := range pendingTables {
102			if p.Story == "" {
103				t.Errorf("pending table %q names no story", p.Table)
104			}
105			if seen[p.Table] {
106				t.Errorf("pending table %q is listed twice", p.Table)
107			}
108			seen[p.Table] = true
109		}
110	}
