431	// finding is one retired mechanism found in a source file.
432	type finding struct {
433		Pos  token.Position // file:line:column
434		What string
435	}
436	
437	// bubbleTeaName returns the local name file gives the bubbletea import: its
438	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
439	// import it (or blank-imports it). A different package that happens to be
440	// called tea is therefore not mistaken for it.
441	func bubbleTeaName(file *ast.File) string {
442		for _, imp := range file.Imports {
443			path, err := strconv.Unquote(imp.Path.Value)
444			if err != nil || path != "github.com/charmbracelet/bubbletea" {
445				continue
446			}
447			switch {
448			case imp.Name == nil:
449				return "tea"
450			case imp.Name.Name == "_":
451				return ""
452			default:
453				return imp.Name.Name
454			}
455		}
456		return ""
457	}
458	
459	// retiredMechanisms reports, in a migrated view's file, every retired
460	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
461	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
462	// imports it) outside declaredViewTicks.
463	// rel is the file's path relative to internal/; it is the key of a declared tick.
464	// RenderedFrame (a method of the viewport frame) is allowed.
465	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
466		var out []finding
467		report := func(pos token.Pos, what string) {
468			out = append(out, finding{Pos: fset.Position(pos), What: what})
469		}
470		tea := bubbleTeaName(file)
471		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
472		// reportTick flags any reference to bubbletea's Tick / Every, called or not
473		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
474		// enclosing "<file>:<function>" is declared.
475		reportTick := func(pos token.Pos, fn, name string) {
476			if name != "Tick" && name != "Every" {
477				return
478			}
479			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
480				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
481			}
482		}
483		isFrame := func(name string) bool {
484			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
485		}
486		visit := func(fn string) func(ast.Node) bool {
487			return func(n ast.Node) bool {
488				switch x := n.(type) {
489				case *ast.CallExpr:
490					sel, ok := x.Fun.(*ast.SelectorExpr)
491					if !ok {
492						break
493					}
494					if sel.Sel.Name == "AdvanceSpinner" {
495						report(x.Pos(), "call to AdvanceSpinner")
496					}
497				case *ast.KeyValueExpr:
498					if id, ok := x.Key.(*ast.Ident); ok {
499						if id.Name == "StatusColumn" {
500							report(id.Pos(), "StatusColumn: key")
501						}
502						if isFrame(id.Name) {
503							report(id.Pos(), "frame field "+id.Name+": set")
504						}
505					}
506				case *ast.Field:
507					for _, id := range x.Names {
508						if isFrame(id.Name) {
509							report(id.Pos(), "frame field "+id.Name)
510						}
511					}
512				case *ast.Ident:
513					// Dot import: a bare Tick / Every that no declaration in the file binds.
514					if tea == "." && x.Obj == nil && !selectors[x] {
515						reportTick(x.Pos(), fn, x.Name)
516					}
517				case *ast.SelectorExpr:
518					selectors[x.Sel] = true
519					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
520						reportTick(x.Pos(), fn, x.Sel.Name)
521					}
522					if isFrame(x.Sel.Name) {
523						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
524					}
525				case *ast.BasicLit:
526					if x.Kind == token.STRING || x.Kind == token.CHAR {
527						s, err := strconv.Unquote(x.Value)
528						if x.Kind == token.CHAR {
529							var q rune
530							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
531							s = string(q)
532						}
533						if err == nil && strings.ContainsAny(s, activityGlyphs) {
534							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
535						}
536					}
537				}
538				return true
539			}
540		}
541		for _, decl := range file.Decls {
542			fn := ""
543			if fd, ok := decl.(*ast.FuncDecl); ok {
544				fn = fd.Name.Name
545			}
546			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
547				for _, spec := range gd.Specs {
548					if isDeclaredGlyphConstant(rel, spec) {
549						continue
550					}
551					ast.Inspect(spec, visit(fn))
552				}
553				continue
554			}
555			ast.Inspect(decl, visit(fn))
556		}
557		return out
558	}
