package explorer

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
)

// ── DEVDESK-139: the frame arrives in its own message ────────────────────────

// The tree: a working row takes its frame from FrameMsg.
func TestAFrameMovesTheRowSpinner(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})
	m = feed(t, m, jobs.ChangedMsg{Runs: []jobs.Run{createRun("new", "new")}})

	for _, frame := range []string{"X", "Y"} {
		m = feed(t, m, jobs.FrameMsg{Frame: frame})
		row, ok := rowFor(m, "new")
		if !ok {
			t.Fatal("the placeholder row is gone")
		}
		if got := iconCell(row); got != frame {
			t.Errorf("icon cell = %q after frame %q, want the spinner", got, frame)
		}
	}
	if len(m.jobs) != 1 {
		t.Errorf("the held runs = %d after a frame, want the 1 from the snapshot", len(m.jobs))
	}
}

// The clone list: a running row takes its frame from FrameMsg.
func TestAFrameMovesTheCloneListSpinner(t *testing.T) {
	h := cloning(t)
	h.emit(found("alpha/api"), began("alpha/api"))

	for _, frame := range []string{"X", "Y"} {
		h.m = feed(t, h.m, jobs.FrameMsg{Frame: frame})
		rows := h.m.clone.table.Table().Rows()
		if len(rows) != 1 {
			t.Fatalf("rows = %v, want the one repository", rows)
		}
		if got := rows[0][colCloneStatus]; !strings.HasPrefix(got, frame+" cloning") {
			t.Errorf("status cell = %q after frame %q, want the new frame", got, frame)
		}
	}
	if got := h.item(0).State; got != jobs.ItemRunning {
		t.Errorf("state = %v, a frame must not touch the run", got)
	}
}

func TestAFrameMovesTheFooterSpinner(t *testing.T) {
	m := loadedModel(t)
	m.loading = true // the tree is reloading: the footer shows a spinner line

	m = feed(t, m, jobs.FrameMsg{RenderedFrame: "<R1>"})

	if footer := m.RenderFooter(160); !strings.Contains(footer, "<R1>") {
		t.Errorf("the footer does not carry the new frame:\n%s", footer)
	}
}
	node := m.deleteTargetNode
	m.deleteTargetNode = nil

	if node == nil {
		return m, nil
	}

	backend := m.shared.Forge
	if backend == nil {
		m.error = "Not connected to a forge"
		return m, nil
	}

	// The whole value goes to the backend, not just an identifier: a permanent
	// deletion addresses the path the forge renames the object to, so the call
	// needs both (see forge.Forge.DeleteNamespace).
	nodeType := node.Type
	id, path := node.ID, node.FullPath

	if m.busy(path) {
		return m, m.footer.Warn(busyMessage)
	}

	work := func() tea.Msg {
		var err error
		if nodeType == NodeTypeGroup {
			err = backend.DeleteNamespace(context.Background(), forge.Namespace{ID: id, Path: path}, permanentlyRemove)
		} else {
			err = backend.DeleteRepository(context.Background(), forge.Repository{ID: id, Path: path}, permanentlyRemove)
		}
		return DeleteCompleteMsg{Error: err, Target: path, DeletedNode: node}
	}
	// The row keeps its place and takes the spinner while the forge works — the
	// same treatment a create gets, and for the same reason: a delete is a
	// network call, and a row that vanished before the answer came would be
	// claiming something that has not happened yet.
	return m, jobs.Start(deleteRun(path, node.Name), work)
}

// removeNode drops node from level, by identity first and by ID as a fallback
// (a refresh may have replaced the pointer since the delete was asked).
func removeNode(level []*TreeNode, node *TreeNode) []*TreeNode {
	for i, n := range level {
		if n == node || (n.ID != "" && n.ID == node.ID) {
			return append(level[:i], level[i+1:]...)
		}
	}
	return level
}

// handleDeleteComplete handles DeleteCompleteMsg
func (m Model) handleDeleteComplete(msg DeleteCompleteMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [explorer] delete: %v", msg.Error)
		return m, m.footer.Error("Delete failed — check logs")
	}
	m.footer.Clear()

	if msg.DeletedNode == nil {
		m.updateTableRows()
		return m, nil
	}

	// The row leaves the level it belongs to — its parent's, which is the
	// current one unless the user drilled elsewhere while the forge worked.
	// Removing it from whatever level was on screen instead would leave it in
